package hospital.management.system;import hospital.management.system.config.DatabaseConnection;import hospital.management.system.dao.LoginDAO;import hospital.management.system.model.LoggedInUser;import hospital.management.system.ui.MainDashboard;import hospital.management.system.util.SessionManager;import javax.swing.*;import javax.swing.border.EmptyBorder;import java.awt.*;import java.awt.event.ActionEvent;import java.awt.event.KeyEvent;import java.sql.Connection;import java.util.Arrays;import java.util.Optional;/** * Modern, responsive and database-backed HMS login screen. */public final class Login extends JFrame {    private static final Color NAVY = new Color(4, 43, 91);    private static final Color NAVY_LIGHT = new Color(5, 100, 143);    private static final Color BLUE = new Color(25, 94, 225);    private static final Color TEAL = new Color(13, 177, 177);    private static final Color PAGE = new Color(245, 248, 252);    private static final Color TEXT = new Color(8, 37, 80);    private static final Color MUTED = new Color(92, 105, 130);    private static final Color BORDER = new Color(205, 215, 230);    private static final Color SUCCESS = new Color(18, 164, 101);    private static final Color ERROR = new Color(221, 62, 70);    private final LoginDAO loginDAO = new LoginDAO();    private JTextField usernameField;    private JPasswordField passwordField;    private JButton showPasswordButton;    private JButton loginButton;    private JButton exitButton;    private JLabel formStatusLabel;    private JLabel databaseStatusLabel;    private char normalEchoCharacter;    private boolean passwordVisible;    public Login() {        configureWindow();        createInterface();        configureKeyboardActions();        setVisible(true);        SwingUtilities.invokeLater(                () -> usernameField.requestFocusInWindow()        );        verifyDatabaseConnection();    }    private void configureWindow() {        setTitle("Smart Hospital Management System");        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);        setSize(1380, 840);        setMinimumSize(new Dimension(1100, 700));        setLocationRelativeTo(null);        getContentPane().setBackground(PAGE);    }    private void createInterface() {        setLayout(new BorderLayout());        JPanel bodyPanel =                new JPanel(new GridLayout(1, 2));        bodyPanel.add(createBrandingPanel());        bodyPanel.add(createLoginArea());        add(bodyPanel, BorderLayout.CENTER);        add(createDatabaseStatusBar(), BorderLayout.SOUTH);    }    private JPanel createBrandingPanel() {        GradientPanel brandingPanel =                new GradientPanel();        brandingPanel.setLayout(new GridBagLayout());        JPanel contentPanel = new JPanel();        contentPanel.setOpaque(false);        contentPanel.setLayout(                new BoxLayout(                        contentPanel,                        BoxLayout.Y_AXIS                )        );        contentPanel.setBorder(                new EmptyBorder(55, 62, 40, 52)        );        JLabel logoLabel =                new JLabel(                        "SMART HMS",                        new VectorIcon(                                IconType.HOSPITAL,                                54,                                Color.WHITE                        ),                        SwingConstants.LEFT                );        logoLabel.setIconTextGap(18);        logoLabel.setForeground(Color.WHITE);        logoLabel.setFont(                new Font(                        "Segoe UI",                        Font.BOLD,                        43                )        );        logoLabel.setAlignmentX(                Component.LEFT_ALIGNMENT        );        JLabel productLabel =                new JLabel(                        "Smart Hospital Management System"                );        productLabel.setForeground(                new Color(35, 232, 226)        );        productLabel.setFont(                new Font(                        "Segoe UI",                        Font.BOLD,                        22                )        );        productLabel.setAlignmentX(                Component.LEFT_ALIGNMENT        );        JPanel accentLine = new JPanel();        accentLine.setBackground(TEAL);        accentLine.setPreferredSize(new Dimension(76, 4));        accentLine.setMaximumSize(new Dimension(76, 4));        accentLine.setAlignmentX(Component.LEFT_ALIGNMENT);        JLabel taglineLabel =                new JLabel(                        "Connected Care. Smarter Management."                );        taglineLabel.setForeground(Color.WHITE);        taglineLabel.setFont(                new Font(                        "Segoe UI",                        Font.PLAIN,                        18                )        );        taglineLabel.setAlignmentX(                Component.LEFT_ALIGNMENT        );        contentPanel.add(logoLabel);        contentPanel.add(Box.createVerticalStrut(13));        contentPanel.add(productLabel);        contentPanel.add(Box.createVerticalStrut(25));        contentPanel.add(accentLine);        contentPanel.add(Box.createVerticalStrut(25));        contentPanel.add(taglineLabel);        contentPanel.add(Box.createVerticalStrut(30));        contentPanel.add(createFeatureRow());        contentPanel.add(Box.createVerticalStrut(30));        contentPanel.add(new HospitalArtwork());        GridBagConstraints constraints =                new GridBagConstraints();        constraints.fill = GridBagConstraints.BOTH;        constraints.weightx = 1;        constraints.weighty = 1;        brandingPanel.add(contentPanel, constraints);        return brandingPanel;    }    /**     * No rectangular feature boxes.     * Only vector icon, title and description.     */    private JPanel createFeatureRow() {        JPanel row =                new JPanel(                        new GridLayout(1, 3, 18, 0)                );        row.setOpaque(false);        row.setMaximumSize(                new Dimension(Integer.MAX_VALUE, 76)        );        row.setPreferredSize(new Dimension(520, 76));        row.setAlignmentX(Component.LEFT_ALIGNMENT);        row.add(                createFeature(                        "Secure",                        "Protected access",                        IconType.SHIELD                )        );        row.add(                createFeature(                        "Role Based",                        "Controlled access",                        IconType.USERS                )        );        row.add(                createFeature(                        "Real-time",                        "Live information",                        IconType.CLOCK                )        );        return row;    }    private JPanel createFeature(            String title,            String description,            IconType iconType    ) {        JPanel feature =                new JPanel(new BorderLayout(10, 0));        feature.setOpaque(false);        CircularIconPanel iconPanel =                new CircularIconPanel(                        iconType                );        JPanel textPanel = new JPanel();        textPanel.setOpaque(false);        textPanel.setLayout(                new BoxLayout(                        textPanel,                        BoxLayout.Y_AXIS                )        );        JLabel titleLabel = new JLabel(title);        titleLabel.setForeground(Color.WHITE);        titleLabel.setFont(                new Font(                        "Segoe UI",                        Font.BOLD,                        13                )        );        JLabel descriptionLabel =                new JLabel(description);        descriptionLabel.setForeground(                new Color(181, 215, 239)        );        descriptionLabel.setFont(                new Font(                        "Segoe UI",                        Font.PLAIN,                        10                )        );        textPanel.add(Box.createVerticalGlue());        textPanel.add(titleLabel);        textPanel.add(Box.createVerticalStrut(3));        textPanel.add(descriptionLabel);        textPanel.add(Box.createVerticalGlue());        feature.add(iconPanel, BorderLayout.WEST);        feature.add(textPanel, BorderLayout.CENTER);        return feature;    }    private JPanel createLoginArea() {        JPanel area =                new JPanel(new GridBagLayout());        area.setBackground(PAGE);        area.setBorder(                new EmptyBorder(30, 45, 30, 45)        );        RoundedPanel card =                new RoundedPanel(Color.WHITE, 28);        card.setLayout(new GridBagLayout());        card.setPreferredSize(                new Dimension(510, 625)        );        card.setBorder(                new EmptyBorder(34, 55, 34, 55)        );        GridBagConstraints constraints =                new GridBagConstraints();        constraints.gridx = 0;        constraints.weightx = 1;        constraints.fill = GridBagConstraints.HORIZONTAL;        constraints.anchor = GridBagConstraints.WEST;        int row = 0;        JLabel medicalIcon =                new JLabel(                        new VectorIcon(                                IconType.MEDICAL,                                44,                                TEAL                        ),                        SwingConstants.CENTER                );        addRow(card, constraints, medicalIcon, row++, 0, 10);        addRow(                card,                constraints,                centeredLabel(                        "Welcome Back",                        new Font(                                "Segoe UI",                                Font.BOLD,                                30                        ),                        TEXT                ),                row++,                0,                5        );        addRow(                card,                constraints,                centeredLabel(                        "Sign in to access your workspace",                        new Font(                                "Segoe UI",                                Font.PLAIN,                                14                        ),                        MUTED                ),                row++,                0,                28        );        addRow(                card,                constraints,                createFormLabel("Username"),                row++,                0,                7        );        addRow(                card,                constraints,                createUsernameInput(),                row++,                0,                18        );        addRow(                card,                constraints,                createFormLabel("Password"),                row++,                0,                7        );        addRow(                card,                constraints,                createPasswordInput(),                row++,                0,                23        );        loginButton =                new PaintedButton(                        "LOGIN",                        new VectorIcon(                                IconType.LOGIN,                                19,                                Color.WHITE                        ),                        BLUE,                        Color.WHITE,                        false                );        styleMainButton(loginButton);        loginButton.addActionListener(                event -> authenticateUser()        );        addRow(                card,                constraints,                loginButton,                row++,                0,                12        );        exitButton =                new PaintedButton(                        "EXIT",                        new VectorIcon(                                IconType.CLOSE,                                18,                                BLUE                        ),                        Color.WHITE,                        BLUE,                        true                );        styleMainButton(exitButton);        exitButton.addActionListener(                event -> exitApplication()        );        addRow(                card,                constraints,                exitButton,                row++,                0,                19        );        formStatusLabel =                centeredLabel(                        "Ready to sign in",                        new Font(                                "Segoe UI",                                Font.PLAIN,                                13                        ),                        MUTED                );        addRow(                card,                constraints,                formStatusLabel,                row++,                0,                10        );        addRow(                card,                constraints,                centeredLabel(                        "Forgot password? Contact administrator",                        new Font(                                "Segoe UI",                                Font.PLAIN,                                13                        ),                        BLUE                ),                row++,                0,                17        );        addRow(                card,                constraints,                createSecurityMessage(),                row,                0,                0        );        area.add(card);        return area;    }    private JPanel createUsernameInput() {        JPanel shell = createInputShell();        shell.add(                new JLabel(                        new VectorIcon(                                IconType.USER,                                20,                                MUTED                        )                ),                BorderLayout.WEST        );        usernameField = new JTextField();        styleTextField(usernameField);        usernameField.setToolTipText(                "Enter your hospital username"        );        shell.add(                usernameField,                BorderLayout.CENTER        );        return shell;    }    private JPanel createPasswordInput() {        JPanel shell = createInputShell();        shell.add(                new JLabel(                        new VectorIcon(                                IconType.LOCK,                                20,                                MUTED                        )                ),                BorderLayout.WEST        );        passwordField = new JPasswordField();        styleTextField(passwordField);        normalEchoCharacter =                passwordField.getEchoChar();        shell.add(                passwordField,                BorderLayout.CENTER        );        showPasswordButton =                new JButton(                        "SHOW",                        new VectorIcon(                                IconType.EYE,                                18,                                BLUE                        )                );        showPasswordButton.setContentAreaFilled(false);        showPasswordButton.setBorderPainted(false);        showPasswordButton.setFocusPainted(false);        showPasswordButton.setOpaque(false);        showPasswordButton.setForeground(BLUE);        showPasswordButton.setFont(                new Font(                        "Segoe UI",                        Font.BOLD,                        11                )        );        showPasswordButton.setCursor(                Cursor.getPredefinedCursor(                        Cursor.HAND_CURSOR                )        );        showPasswordButton.addActionListener(                event -> togglePassword()        );        shell.add(                showPasswordButton,                BorderLayout.EAST        );        return shell;    }    private JPanel createInputShell() {        JPanel shell =                new JPanel(new BorderLayout(10, 0));        shell.setBackground(Color.WHITE);        shell.setBorder(                BorderFactory.createCompoundBorder(                        BorderFactory.createLineBorder(BORDER),                        new EmptyBorder(0, 14, 0, 9)                )        );        shell.setPreferredSize(                new Dimension(400, 51)        );        return shell;    }    private void styleTextField(            JTextField field    ) {        field.setFont(                new Font(                        "Segoe UI",                        Font.PLAIN,                        15                )        );        field.setForeground(TEXT);        field.setCaretColor(BLUE);        field.setBackground(Color.WHITE);        field.setBorder(new EmptyBorder(0, 2, 0, 2));    }    private JLabel createFormLabel(            String text    ) {        JLabel label = new JLabel(text);        label.setFont(                new Font(                        "Segoe UI",                        Font.BOLD,                        14                )        );        label.setForeground(TEXT);        return label;    }    private JLabel centeredLabel(            String text,            Font font,            Color color    ) {        JLabel label =                new JLabel(                        text,                        SwingConstants.CENTER                );        label.setFont(font);        label.setForeground(color);        return label;    }    private void addRow(            JPanel panel,            GridBagConstraints constraints,            Component component,            int row,            int top,            int bottom    ) {        constraints.gridy = row;        constraints.insets =                new Insets(top, 0, bottom, 0);        panel.add(component, constraints);    }    private void styleMainButton(            JButton button    ) {        button.setIconTextGap(9);        button.setFont(                new Font(                        "Segoe UI",                        Font.BOLD,                        15                )        );        button.setFocusPainted(false);        button.setPreferredSize(                new Dimension(400, 50)        );        button.setBorder(                new EmptyBorder(13, 18, 13, 18)        );        button.setCursor(                Cursor.getPredefinedCursor(                        Cursor.HAND_CURSOR                )        );    }    private JPanel createSecurityMessage() {        RoundedPanel panel =                new RoundedPanel(                        new Color(229, 241, 255),                        14                );        panel.setLayout(                new FlowLayout(                        FlowLayout.CENTER,                        8,                        10                )        );        panel.setPreferredSize(                new Dimension(400, 42)        );        panel.add(                new JLabel(                        new VectorIcon(                                IconType.SHIELD,                                18,                                BLUE                        )                )        );        JLabel textLabel =                new JLabel(                        "Access securely verified from database"                );        textLabel.setFont(                new Font(                        "Segoe UI",                        Font.PLAIN,                        12                )        );        textLabel.setForeground(BLUE);        panel.add(textLabel);        return panel;    }    private JPanel createDatabaseStatusBar() {        JPanel bar =                new JPanel(                        new FlowLayout(                                FlowLayout.LEFT,                                12,                                10                        )                );        bar.setBackground(Color.WHITE);        bar.setBorder(                BorderFactory.createMatteBorder(                        1,                        0,                        0,                        0,                        BORDER                )        );        bar.setPreferredSize(                new Dimension(0, 44)        );        databaseStatusLabel =                new JLabel(                        "Checking database connection...",                        new VectorIcon(                                IconType.STATUS,                                14,                                new Color(214, 137, 0)                        ),                        SwingConstants.LEFT                );        databaseStatusLabel.setIconTextGap(8);        databaseStatusLabel.setFont(                new Font(                        "Segoe UI",                        Font.PLAIN,                        12                )        );        databaseStatusLabel.setForeground(                new Color(184, 111, 0)        );        bar.add(databaseStatusLabel);        return bar;    }    private void configureKeyboardActions() {        JRootPane rootPane =                getRootPane();        rootPane.getInputMap(                        JComponent.WHEN_IN_FOCUSED_WINDOW                )                .put(                        KeyStroke.getKeyStroke(                                KeyEvent.VK_ENTER,                                0                        ),                        "login"                );        rootPane.getActionMap()                .put(                        "login",                        new AbstractAction() {                            @Override                            public void actionPerformed(                                    ActionEvent event                            ) {                                authenticateUser();                            }                        }                );        rootPane.getInputMap(                        JComponent.WHEN_IN_FOCUSED_WINDOW                )                .put(                        KeyStroke.getKeyStroke(                                KeyEvent.VK_ESCAPE,                                0                        ),                        "exit"                );        rootPane.getActionMap()                .put(                        "exit",                        new AbstractAction() {                            @Override                            public void actionPerformed(                                    ActionEvent event                            ) {                                exitApplication();                            }                        }                );    }    private void togglePassword() {        passwordVisible = !passwordVisible;        passwordField.setEchoChar(                passwordVisible                        ? (char) 0                        : normalEchoCharacter        );        showPasswordButton.setText(                passwordVisible                        ? "HIDE"                        : "SHOW"        );        passwordField.requestFocusInWindow();    }    private void authenticateUser() {        String username =                usernameField                        .getText()                        .trim();        char[] password =                passwordField.getPassword();        if (username.isBlank()) {            showFormError(                    "Please enter your username."            );            usernameField.requestFocusInWindow();            Arrays.fill(password, '\0');            return;        }        if (password.length == 0) {            showFormError(                    "Please enter your password."            );            passwordField.requestFocusInWindow();            return;        }        setFormEnabled(false);        formStatusLabel.setForeground(BLUE);        formStatusLabel.setText(                "Verifying credentials..."        );        SwingWorker<Optional<LoggedInUser>, Void> worker =                new SwingWorker<>() {                    @Override                    protected Optional<LoggedInUser>                    doInBackground() throws Exception {                        return loginDAO.authenticateUser(                                username,                                password                        );                    }                    @Override                    protected void done() {                        Arrays.fill(password, '\0');                        setFormEnabled(true);                        try {                            Optional<LoggedInUser> result =                                    get();                            if (result.isEmpty()) {                                passwordField.setText("");                                showFormError(                                        "Invalid username or password."                                );                                return;                            }                            SessionManager.startSession(                                    result.get()                            );                            formStatusLabel.setForeground(                                    SUCCESS                            );                            formStatusLabel.setText(                                    "Login successful. Opening dashboard..."                            );                            dispose();                            SwingUtilities.invokeLater(                                    MainDashboard::new                            );                        } catch (Exception exception) {                            showFormError(                                    "Login failed: "                                            + rootMessage(                                            exception                                    )                            );                        }                    }                };        worker.execute();    }    private void verifyDatabaseConnection() {        SwingWorker<Boolean, Void> worker =                new SwingWorker<>() {                    @Override                    protected Boolean doInBackground() {                        try (                                Connection ignored =                                        DatabaseConnection                                                .getConnection()                        ) {                            return true;                        } catch (Exception exception) {                            return false;                        }                    }                    @Override                    protected void done() {                        try {                            boolean connected =                                    Boolean.TRUE.equals(                                            get()                                    );                            databaseStatusLabel.setText(                                    connected                                            ? "Database Connected"                                            : "Database connection unavailable"                            );                            databaseStatusLabel.setForeground(                                    connected                                            ? SUCCESS                                            : ERROR                            );                            databaseStatusLabel.setIcon(                                    new VectorIcon(                                            IconType.STATUS,                                            14,                                            connected                                                    ? SUCCESS                                                    : ERROR                                    )                            );                        } catch (Exception exception) {                            databaseStatusLabel.setText(                                    "Database status unavailable"                            );                            databaseStatusLabel.setForeground(                                    ERROR                            );                        }                    }                };        worker.execute();    }    private void setFormEnabled(            boolean enabled    ) {        usernameField.setEnabled(enabled);        passwordField.setEnabled(enabled);        showPasswordButton.setEnabled(enabled);        loginButton.setEnabled(enabled);        exitButton.setEnabled(enabled);        loginButton.setText(                enabled                        ? "LOGIN"                        : "PLEASE WAIT..."        );    }    private void showFormError(            String message    ) {        formStatusLabel.setForeground(ERROR);        formStatusLabel.setText(message);        Toolkit.getDefaultToolkit().beep();    }    private void exitApplication() {        int result =                JOptionPane.showConfirmDialog(                        this,                        "Do you want to close Smart HMS?",                        "Exit Application",                        JOptionPane.YES_NO_OPTION,                        JOptionPane.QUESTION_MESSAGE                );        if (result == JOptionPane.YES_OPTION) {            dispose();            System.exit(0);        }    }    private static String rootMessage(            Throwable throwable    ) {        Throwable current = throwable;        while (current.getCause() != null) {            current = current.getCause();        }        return current.getMessage() == null                ? "Unknown error"                : current.getMessage();    }    public static void main(            String[] arguments    ) {        SwingUtilities.invokeLater(                () -> {                    try {                        UIManager.setLookAndFeel(                                UIManager                                        .getSystemLookAndFeelClassName()                        );                    } catch (Exception ignored) {                    }                    new Login();                }        );    }    private static final class CircularIconPanel            extends JPanel {        CircularIconPanel(                IconType iconType        ) {            setOpaque(false);            setPreferredSize(new Dimension(48, 48));            setLayout(new GridBagLayout());            add(                    new JLabel(                            new VectorIcon(                                    iconType,                                    25,                                    Color.WHITE                            )                    )            );        }        @Override        protected void paintComponent(                Graphics graphics        ) {            Graphics2D graphics2D =                    (Graphics2D)                            graphics.create();            graphics2D.setRenderingHint(                    RenderingHints.KEY_ANTIALIASING,                    RenderingHints.VALUE_ANTIALIAS_ON            );            graphics2D.setColor(                    new Color(13, 177, 177, 75)            );            graphics2D.fillOval(                    1,                    1,                    getWidth() - 2,                    getHeight() - 2            );            graphics2D.setColor(                    new Color(94, 238, 232, 180)            );            graphics2D.drawOval(                    1,                    1,                    getWidth() - 3,                    getHeight() - 3            );            graphics2D.dispose();            super.paintComponent(graphics);        }    }    private static final class PaintedButton            extends JButton {        private final Color fillColor;        private final Color textColor;        private final boolean outlined;        private boolean hovered;        private boolean pressed;        PaintedButton(                String text,                Icon icon,                Color fillColor,                Color textColor,                boolean outlined        ) {            super(text, icon);            this.fillColor = fillColor;            this.textColor = textColor;            this.outlined = outlined;            setContentAreaFilled(false);            setBorderPainted(false);            setOpaque(false);            addMouseListener(                    new java.awt.event.MouseAdapter() {                        @Override                        public void mouseEntered(                                java.awt.event.MouseEvent event                        ) {                            hovered = true;                            repaint();                        }                        @Override                        public void mouseExited(                                java.awt.event.MouseEvent event                        ) {                            hovered = false;                            pressed = false;                            repaint();                        }                        @Override                        public void mousePressed(                                java.awt.event.MouseEvent event                        ) {                            pressed = true;                            repaint();                        }                        @Override                        public void mouseReleased(                                java.awt.event.MouseEvent event                        ) {                            pressed = false;                            repaint();                        }                    }            );        }        @Override        protected void paintComponent(                Graphics graphics        ) {            Graphics2D graphics2D =                    (Graphics2D)                            graphics.create();            graphics2D.setRenderingHint(                    RenderingHints.KEY_ANTIALIASING,                    RenderingHints.VALUE_ANTIALIAS_ON            );            if (outlined) {                graphics2D.setColor(                        hovered                                ? new Color(237, 245, 255)                                : Color.WHITE                );                graphics2D.fillRoundRect(                        1,                        1,                        getWidth() - 3,                        getHeight() - 3,                        16,                        16                );                graphics2D.setColor(BLUE);                graphics2D.setStroke(new BasicStroke(1.8f));                graphics2D.drawRoundRect(                        1,                        1,                        getWidth() - 3,                        getHeight() - 3,                        16,                        16                );            } else {                Color endColor =                        pressed                                ? fillColor.darker()                                : fillColor;                Color startColor =                        hovered                                ? brighten(TEAL, 20)                                : TEAL;                graphics2D.setPaint(                        new GradientPaint(                                0,                                0,                                startColor,                                getWidth(),                                getHeight(),                                endColor                        )                );                graphics2D.fillRoundRect(                        0,                        0,                        getWidth(),                        getHeight(),                        16,                        16                );            }            graphics2D.dispose();            setForeground(                    isEnabled()                            ? textColor                            : new Color(230, 235, 242)            );            super.paintComponent(graphics);        }        private static Color brighten(                Color color,                int amount        ) {            return new Color(                    Math.min(255, color.getRed() + amount),                    Math.min(255, color.getGreen() + amount),                    Math.min(255, color.getBlue() + amount)            );        }    }    private static final class RoundedPanel            extends JPanel {        private final Color fillColor;        private final int radius;        RoundedPanel(                Color fillColor,                int radius        ) {            this.fillColor = fillColor;            this.radius = radius;            setOpaque(false);        }        @Override        protected void paintComponent(                Graphics graphics        ) {            Graphics2D graphics2D =                    (Graphics2D)                            graphics.create();            graphics2D.setRenderingHint(                    RenderingHints.KEY_ANTIALIASING,                    RenderingHints.VALUE_ANTIALIAS_ON            );            graphics2D.setColor(                    new Color(13, 39, 74, 18)            );            graphics2D.fillRoundRect(                    4,                    7,                    getWidth() - 8,                    getHeight() - 9,                    radius,                    radius            );            graphics2D.setColor(fillColor);            graphics2D.fillRoundRect(                    1,                    1,                    getWidth() - 7,                    getHeight() - 9,                    radius,                    radius            );            graphics2D.dispose();            super.paintComponent(graphics);        }    }    private static final class GradientPanel            extends JPanel {        GradientPanel() {            setOpaque(false);        }        @Override        protected void paintComponent(                Graphics graphics        ) {            Graphics2D graphics2D =                    (Graphics2D)                            graphics.create();            graphics2D.setPaint(                    new GradientPaint(                            0,                            0,                            NAVY,                            getWidth(),                            getHeight(),                            NAVY_LIGHT                    )            );            graphics2D.fillRect(                    0,                    0,                    getWidth(),                    getHeight()            );            graphics2D.setColor(                    new Color(23, 163, 180, 45)            );            graphics2D.fillOval(                    getWidth() - 210,                    -100,                    330,                    330            );            graphics2D.fillOval(                    -150,                    getHeight() - 230,                    350,                    350            );            graphics2D.dispose();            super.paintComponent(graphics);        }    }    private static final class HospitalArtwork            extends JPanel {        HospitalArtwork() {            setOpaque(false);            setPreferredSize(                    new Dimension(520, 300)            );            setMaximumSize(                    new Dimension(                            Integer.MAX_VALUE,                            300                    )            );            setAlignmentX(                    Component.LEFT_ALIGNMENT            );        }        @Override        protected void paintComponent(                Graphics graphics        ) {            Graphics2D g =                    (Graphics2D)                            graphics.create();            g.setRenderingHint(                    RenderingHints.KEY_ANTIALIASING,                    RenderingHints.VALUE_ANTIALIAS_ON            );            int centerX = getWidth() / 2;            int baseY = getHeight() - 30;            g.setColor(                    new Color(255, 255, 255, 23)            );            g.fillRoundRect(                    18,                    5,                    getWidth() - 36,                    getHeight() - 15,                    28,                    28            );            g.setColor(                    new Color(233, 247, 250)            );            g.fillRoundRect(                    centerX - 120,                    baseY - 165,                    240,                    165,                    18,                    18            );            g.setColor(NAVY);            g.setStroke(new BasicStroke(5));            g.drawRoundRect(                    centerX - 120,                    baseY - 165,                    240,                    165,                    18,                    18            );            g.setColor(TEAL);            g.fillOval(                    centerX - 35,                    baseY - 205,                    70,                    70            );            g.setColor(Color.WHITE);            g.fillRoundRect(                    centerX - 8,                    baseY - 190,                    16,                    42,                    4,                    4            );            g.fillRoundRect(                    centerX - 21,                    baseY - 177,                    42,                    16,                    4,                    4            );            g.setColor(                    new Color(111, 190, 205)            );            for (int row = 0; row < 2; row++) {                for (                        int column = 0;                        column < 4;                        column++                ) {                    g.fillRoundRect(                            centerX - 94 + column * 53,                            baseY - 125 + row * 44,                            29,                            26,                            5,                            5                    );                }            }            g.setColor(NAVY);            g.drawRect(                    centerX - 25,                    baseY - 61,                    50,                    61            );            g.drawLine(                    centerX,                    baseY - 61,                    centerX,                    baseY            );            g.dispose();        }    }    private enum IconType {        HOSPITAL,        SHIELD,        USERS,        CLOCK,        MEDICAL,        USER,        LOCK,        EYE,        LOGIN,        CLOSE,        STATUS    }    /**     * Font-independent icons. No emojis, so no square glyphs.     */    private static final class VectorIcon            implements Icon {        private final IconType type;        private final int size;        private final Color color;        VectorIcon(                IconType type,                int size,                Color color        ) {            this.type = type;            this.size = size;            this.color = color;        }        @Override        public int getIconWidth() {            return size;        }        @Override        public int getIconHeight() {            return size;        }        @Override        public void paintIcon(                Component component,                Graphics graphics,                int x,                int y        ) {            Graphics2D g =                    (Graphics2D)                            graphics.create();            g.translate(x, y);            g.setRenderingHint(                    RenderingHints.KEY_ANTIALIASING,                    RenderingHints.VALUE_ANTIALIAS_ON            );            g.setColor(color);            float scale = size / 32f;            g.setStroke(                    new BasicStroke(                            Math.max(1.7f, 2.2f * scale),                            BasicStroke.CAP_ROUND,                            BasicStroke.JOIN_ROUND                    )            );            switch (type) {                case HOSPITAL -> {                    g.drawOval(1, 1, size - 3, size - 3);                    drawCross(g, scale);                }                case MEDICAL ->                        drawCross(g, scale);                case SHIELD -> {                    Polygon shield = new Polygon(                            new int[]{                                    Math.round(16 * scale),                                    Math.round(27 * scale),                                    Math.round(25 * scale),                                    Math.round(16 * scale),                                    Math.round(7 * scale),                                    Math.round(5 * scale)                            },                            new int[]{                                    Math.round(3 * scale),                                    Math.round(8 * scale),                                    Math.round(20 * scale),                                    Math.round(29 * scale),                                    Math.round(20 * scale),                                    Math.round(8 * scale)                            },                            6                    );                    g.drawPolygon(shield);                    g.drawLine(                            Math.round(10 * scale),                            Math.round(16 * scale),                            Math.round(15 * scale),                            Math.round(21 * scale)                    );                    g.drawLine(                            Math.round(15 * scale),                            Math.round(21 * scale),                            Math.round(23 * scale),                            Math.round(12 * scale)                    );                }                case USERS -> {                    g.drawOval(                            Math.round(4 * scale),                            Math.round(5 * scale),                            Math.round(9 * scale),                            Math.round(9 * scale)                    );                    g.drawOval(                            Math.round(19 * scale),                            Math.round(5 * scale),                            Math.round(9 * scale),                            Math.round(9 * scale)                    );                    g.drawArc(                            0,                            Math.round(15 * scale),                            Math.round(17 * scale),                            Math.round(13 * scale),                            0,                            180                    );                    g.drawArc(                            Math.round(15 * scale),                            Math.round(15 * scale),                            Math.round(17 * scale),                            Math.round(13 * scale),                            0,                            180                    );                }                case CLOCK -> {                    g.drawOval(                            Math.round(4 * scale),                            Math.round(4 * scale),                            Math.round(24 * scale),                            Math.round(24 * scale)                    );                    g.drawLine(                            Math.round(16 * scale),                            Math.round(9 * scale),                            Math.round(16 * scale),                            Math.round(17 * scale)                    );                    g.drawLine(                            Math.round(16 * scale),                            Math.round(17 * scale),                            Math.round(22 * scale),                            Math.round(20 * scale)                    );                }                case USER -> {                    g.drawOval(                            Math.round(11 * scale),                            Math.round(4 * scale),                            Math.round(10 * scale),                            Math.round(10 * scale)                    );                    g.drawArc(                            Math.round(5 * scale),                            Math.round(15 * scale),                            Math.round(22 * scale),                            Math.round(14 * scale),                            0,                            180                    );                }                case LOCK -> {                    g.drawArc(                            Math.round(8 * scale),                            Math.round(3 * scale),                            Math.round(16 * scale),                            Math.round(18 * scale),                            0,                            180                    );                    g.drawRoundRect(                            Math.round(5 * scale),                            Math.round(13 * scale),                            Math.round(22 * scale),                            Math.round(16 * scale),                            5,                            5                    );                }                case EYE -> {                    g.drawOval(                            Math.round(4 * scale),                            Math.round(9 * scale),                            Math.round(24 * scale),                            Math.round(14 * scale)                    );                    g.drawOval(                            Math.round(13 * scale),                            Math.round(12 * scale),                            Math.round(6 * scale),                            Math.round(6 * scale)                    );                }                case LOGIN -> {                    g.drawRoundRect(                            Math.round(3 * scale),                            Math.round(4 * scale),                            Math.round(16 * scale),                            Math.round(24 * scale),                            4,                            4                    );                    g.drawLine(                            Math.round(11 * scale),                            Math.round(16 * scale),                            Math.round(29 * scale),                            Math.round(16 * scale)                    );                    g.drawLine(                            Math.round(24 * scale),                            Math.round(11 * scale),                            Math.round(29 * scale),                            Math.round(16 * scale)                    );                    g.drawLine(                            Math.round(24 * scale),                            Math.round(21 * scale),                            Math.round(29 * scale),                            Math.round(16 * scale)                    );                }                case CLOSE -> {                    g.drawLine(                            Math.round(7 * scale),                            Math.round(7 * scale),                            Math.round(25 * scale),                            Math.round(25 * scale)                    );                    g.drawLine(                            Math.round(25 * scale),                            Math.round(7 * scale),                            Math.round(7 * scale),                            Math.round(25 * scale)                    );                }                case STATUS ->                        g.fillOval(                                size / 4,                                size / 4,                                size / 2,                                size / 2                        );            }            g.dispose();        }        private static void drawCross(                Graphics2D graphics,                float scale        ) {            graphics.fillRoundRect(                    Math.round(13 * scale),                    Math.round(3 * scale),                    Math.round(6 * scale),                    Math.round(26 * scale),                    4,                    4            );            graphics.fillRoundRect(                    Math.round(3 * scale),                    Math.round(13 * scale),                    Math.round(26 * scale),                    Math.round(6 * scale),                    4,                    4            );        }    }}